SELECT rgbbright, rgbcoloracc, rgbzones, rgbmodes, 
       (rgbbright::numeric / 100) * (rgbcoloracc::numeric / 10) * (0.5 + rgbmodes::numeric / 20) AS riq_with_modes
FROM rgb LIMIT 5;

SELECT rgbbright, rgbcoloracc, rgbzones, 
       rgbbright / 100.0 * rgbcoloracc / 10.0 * (0.5 + rgbzones / 20.0) AS riq
FROM rgb WHERE rgbbright = 95 AND rgbcoloracc = 99.1 AND rgbzones = 10;
